#!/bin/bash
# Stage1-vs-stage2 regression harness for the pliron self-host worktree.
#
# Runs a compiletest suite twice — once with the stage2 rustc (pliron-built,
# i.e. code generated by this backend) and once with the stage1 rustc
# (LLVM-built baseline) — then diffs the failure sets. Failures that only
# appear at stage 2 are pliron miscompile candidates; failures at both
# stages are baseline/feature gaps, not regressions.
#
#   selfhost/verify.sh [WORKTREE] [SUITE] [--stage1-only|--stage2-only]
#
# Defaults: WORKTREE=$RUST_CHECKOUT-sh or sibling rust-sh, SUITE=tests/ui.
# Results land in $WORKTREE/verify-out/{stage1,stage2}.{log,failures} plus
# verify-out/regressions (tests failing at stage 2 but not stage 1).
#
# Notes:
# - Darwin: rustc shells out to `rust-objcopy` for -Cstrip=debuginfo (which
#   compiletest passes). The stage2 sysroot has none; we put the pinned
#   nightly's llvm-tools bin on PATH.
# - compiletest fingerprints cache results per rustc binary; --force-rerun
#   keeps stale "up-to-date" skips from hiding failures.
# - A miscompiled stage2 rustc can deadlock at 0% CPU (recursive panic while
#   demangling a backtrace). A background watchdog kills rustc processes
#   from this worktree that idle >WATCHDOG_MIN minutes; the stragglers then
#   show up as ordinary failures to investigate.
# r[impl verify.selfhost.stage2]
# r[verify model.equiv]
# r[verify verify.selfhost.stage2]
# r[verify verify.selfhost.watchdog]
set -uo pipefail
B="$(cd "$(dirname "$0")/.." && pwd)"
RUST="${RUST_CHECKOUT:-$B/../rust}"
[[ -d "$RUST/tests/ui" ]] || RUST="$HOME/work/rust"
WT="${1:-$RUST-sh}"
SUITE="${2:-tests/ui}"
ONLY="${3:-both}"
OUT="$WT/verify-out"
WATCHDOG_MIN=5

HOST="$(rustc +nightly-2026-10-22 -vV | sed -n 's/^host: //p')"
export PATH="$HOME/.rustup/toolchains/nightly-2026-10-22-$HOST/lib/rustlib/$HOST/bin:$PATH"

mkdir -p "$OUT"
cd "$WT"
# Which backend source this stage2 was built from (selfhost/setup.sh).
REV=$(cat compiler/rustc_codegen_pliron/.pliron-src-rev 2>/dev/null || echo "unknown (re-run selfhost/setup.sh)")
echo "verify: backend source $REV" | tee "$OUT/backend-rev"

kill_stragglers() {
    # Only stage1/stage2 test-invoked rustc — the bootstrap driver rustc
    # and stage codegen rustc legitimately idle while orchestrating.
    # etime is MM:SS / HH:MM:SS / D-HH:MM:SS; only kill idle (<0.5% cpu).
    ps -eo pid,%cpu,etime,comm | awk -v w="$WT/build" -v m="$WATCHDOG_MIN" '
        index($0, w) && $0 ~ /\/stage[12]\/bin\/rustc$/ {
            n = split($3, t, ":")
            mins = (n == 2) ? t[1] : m + 1
            if ($3 ~ /-/ || mins >= m) { if ($2 + 0 < 0.5) print $1 }
        }
    ' | xargs -I{} kill -9 {} 2>/dev/null
}

# r[impl verify.selfhost.watchdog]
watchdog() {
    while :; do sleep 60; kill_stragglers; done
}

# Result cache (2026-10-29, untested: needs a stage-2 checkout). A stage's
# failure list depends only on (rustc binary, suite tree, suite args). Stage 1
# is the LLVM baseline and rarely changes, so its share of the wall time is
# skipped whenever the key matches; stage 2 is reused only when the very same
# binary is re-verified (resumed run, harness-only change).
# VERIFY_NOCACHE=1 disables it. Entries: $OUT/cache/stage<N>-<key>.{failures,done}.
stage_key() {
    local bin="$WT/build/$HOST/stage$1/bin/rustc"
    [ -x "$bin" ] || return 1
    local tree
    tree=$(git -C "$WT" rev-parse "HEAD:${SUITE}" 2>/dev/null) || return 1
    # A dirty suite tree means no cache.
    [ -z "$(git -C "$WT" status --porcelain -- "$SUITE")" ] || return 1
    echo "$(shasum -a 256 "$bin" | cut -c1-16)-$(echo "$tree-$SUITE" | shasum -a 256 | cut -c1-12)"
}

run_stage() {
    local st="$1" key=""
    mkdir -p "$OUT/cache"
    if [ -z "${VERIFY_NOCACHE:-}" ] && key=$(stage_key "$st") && [ -s "$OUT/cache/stage$st-$key.done" ]; then
        cp "$OUT/cache/stage$st-$key.failures" "$OUT/stage$st.failures"
        rm -f "$OUT/stage$st.incomplete"
        echo "stage$st: $(wc -l < "$OUT/stage$st.failures" | tr -d ' ') failures (CACHED, key $key; VERIFY_NOCACHE=1 to rerun)"
        return
    fi
    key=$(stage_key "$st") || key=""
    watchdog & local wd=$!
    ./x test "$SUITE" --stage "$st" --force-rerun > "$OUT/stage$st.log" 2>&1
    local rc=$?
    kill "$wd" 2>/dev/null
    # The canonical list is compiletest's trailing "failures:" block of
    # indented "[suite] path" lines.
    awk '/^failures:$/ {f=1; next} f && /^    \[/ {print; next} f {f=0}' \
        "$OUT/stage$st.log" | sort -u > "$OUT/stage$st.failures"
    if ! grep -q "^test result:" "$OUT/stage$st.log"; then
        echo "stage$st: INCOMPLETE — no 'test result:' summary in log (x exit $rc); failure list not trustworthy"
        touch "$OUT/stage$st.incomplete"
    else
        rm -f "$OUT/stage$st.incomplete"
        echo "stage$st: $(wc -l < "$OUT/stage$st.failures" | tr -d ' ') failures (x exit $rc)"
        if [ -n "$key" ]; then   # only complete runs are cached
            cp "$OUT/stage$st.failures" "$OUT/cache/stage$st-$key.failures" && echo "$rc" > "$OUT/cache/stage$st-$key.done"
        fi
    fi
}

case "$ONLY" in
    --stage1-only) run_stage 1 ;;
    --stage2-only) run_stage 2 ;;
    *)
        run_stage 2
        run_stage 1
        if [ -e "$OUT/stage1.incomplete" ] || [ -e "$OUT/stage2.incomplete" ]; then
            echo "== comparison skipped: a stage run did not complete"
            exit 1
        fi
        comm -23 "$OUT/stage2.failures" "$OUT/stage1.failures" > "$OUT/regressions"
        comm -13 "$OUT/stage2.failures" "$OUT/stage1.failures" > "$OUT/stage1-only"
        echo "== stage2-only failures (pliron regression candidates): $(wc -l < "$OUT/regressions" | tr -d ' ')"
        cat "$OUT/regressions"
        ;;
esac
